def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_constraints = {
        name: [(bounds[0], bounds[1])] for name, bounds in roots.items()
    }

    def active_dependencies(row):
        return [
            dep for dep in row['deps']
            if not dep.get('feature') or dep['feature'] in features
        ]

    def satisfies(name, version, constraints):
        if not all(low <= version <= high for low, high in constraints):
            return False
        if version in blocked.get(name, ()):
            return False
        if name in pins and version != pins[name]:
            return False
        return True

    def rows_for(name, constraints):
        return sorted(
            (row for row in packages.get(name, [])
             if satisfies(name, row['version'], constraints)),
            key=lambda row: row['version'],
            reverse=True,
        )

    def is_acyclic(selected):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep in active_dependencies(selected[name]):
                dep_name = dep['name']
                if dep_name not in selected or not visit(dep_name):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected)

    def search(selected, constraints):
        nonlocal best_vector, best_versions

        # Dependencies discovered later can further constrain selected packages.
        for name, row in selected.items():
            if not satisfies(name, row['version'], constraints.get(name, [])):
                return

        pending = set(constraints) - set(selected)
        if not pending:
            if not is_acyclic(selected):
                return
            vector = version_vector(names, selected)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in selected.items()
                }
            return

        # An optimistic bound permits unconstrained packages their best version
        # and constrained packages their best currently valid row.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in selected:
                    upper.append(selected[name]['version'])
                elif name in constraints:
                    options = rows_for(name, constraints[name])
                    upper.append(max((row['version'] for row in options), default=-1))
                else:
                    available = [row['version'] for row in packages.get(name, [])]
                    upper.append(max([-1] + available))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        for row in rows_for(name, constraints[name]):
            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = {
                key: list(value) for key, value in constraints.items()
            }
            for dep in active_dependencies(row):
                dep_name = dep['name']
                next_constraints.setdefault(dep_name, []).append(
                    (dep['min'], dep['max'])
                )
            search(next_selected, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
